.mask-indicator{color:var(--candidate);font-size:12px;font-variant-numeric:tabular-nums;white-space:nowrap}#chart.mask-active{touch-action:none}.chart-panel #maskChart{position:absolute;inset:0;z-index:2;pointer-events:none}.chart-panel #hoverChart{z-index:3}
.sim-panel-head{display:flex;align-items:center;gap:3px;margin-bottom:9px}.sim-panel-head h2{margin:0;font-size:15px}.sim-groups{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.sim-subpanel{min-width:0;border:1px solid var(--line);border-radius:7px;background:#0e1825;overflow:hidden}.sim-subpanel.manual{grid-column:1/-1}.sim-subpanel>summary{padding:9px 11px;background:#172336;color:var(--text);font-size:14px;font-weight:800;cursor:pointer;user-select:none}.sim-subpanel>summary::marker{color:var(--accent)}.sim-subpanel>summary:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}.subpanel-controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:9px 12px;align-items:center;padding:11px}.subpanel-controls>label:not(.switch){display:grid;grid-template-columns:minmax(0,1fr) minmax(72px,46%);align-items:center;gap:5px}.subpanel-controls input[type=number],.subpanel-controls select{width:100%;min-width:0;margin-left:0}.subpanel-controls>.switch{min-height:34px}.manual-controls button{margin-left:0;min-height:34px}.manual-controls .sim-hint{grid-column:span 2}.sim-subpanel .sim-result{margin:0 11px 11px}.auto-note{color:var(--muted);font-size:11px;margin:0;padding:0 11px 11px}.auto-table td:first-child,.auto-table th:first-child{text-align:left}.strategy-a{color:#73b7ff}.strategy-b{color:#d9a7ff}
.annotation-panel{margin-top:10px;padding:10px 11px}.annotation-controls{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.annotation-controls textarea{flex:1 1 260px;min-height:38px;resize:vertical;border:1px solid var(--line);border-radius:4px;background:#0b1420;color:var(--text);padding:7px}.annotation-target{color:var(--candidate);min-width:185px}.annotation-list{margin-top:9px;max-height:220px;overflow:auto}.annotation-list td:nth-child(3){white-space:normal;text-align:left;min-width:180px}.annotation-list button{margin:0 0 0 5px;padding:4px 7px}.annotation-good{color:#54d98c}.annotation-bad{color:#ff7180}.annotation-watch{color:#ffc857}.chart-panel #annotationChart{position:absolute;inset:0;pointer-events:none}
.trade-workspace{display:grid;grid-template-columns:minmax(0,2fr) minmax(340px,1fr);gap:10px}.trade-workspace>.sim-panel,.trade-workspace>.live-panel{margin-top:10px}.live-panel{padding:10px 11px;border-color:#8b5b22;background:#19170f}.live-head,.live-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.live-head h2{font-size:15px;margin:0 auto 0 0;color:#ffd27a}.runtime-badge{display:inline-block;padding:3px 7px;border-radius:999px;background:#36404d;color:#dce7f5;font-size:11px}.runtime-ok{background:#174c38;color:#8df0be}.runtime-warn{background:#634915;color:#ffe19a}.runtime-bad{background:#682b33;color:#ffb3ba}.live-warning{margin:8px 0;color:#ffca6a;font-size:12px}.live-actions button{margin-left:0}.live-actions button:disabled{cursor:not-allowed;opacity:.45}.live-status{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;margin-top:9px;background:#4f4029;border:1px solid #4f4029}.live-status>div{background:#111923;padding:6px 8px;min-height:45px;overflow-wrap:anywhere}.live-status span{display:block;color:var(--muted);font-size:10px}.live-events{margin-top:8px;padding:7px;background:#0b1420;border:1px solid var(--line);border-radius:4px;white-space:pre-wrap;word-break:break-word;max-height:145px;overflow:auto;font:11px/1.45 ui-monospace,monospace}.chart-panel #liveChart{position:absolute;inset:0;pointer-events:none;z-index:1}
@media(max-width:700px){.groupbar{display:flex;flex-direction:column;align-items:stretch;gap:7px;padding:8px}.groupbar>.section-no{align-self:flex-start}.group-row{display:grid;grid-template-columns:82px minmax(0,1fr) 82px;gap:8px;width:100%;align-items:center}.group-row label{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:6px;min-width:0}.group-row select{width:100%;min-width:0;max-width:none;margin-left:0}.group-row button{width:100%;min-height:46px;font-size:16px;padding:8px 5px}.groupbar>#manageGroups{width:100%;min-height:42px}.groupbar .wide{grid-column:auto}.groupbar select{max-width:none;width:100%}.groupbar .wide{grid-column:1/-1}.groupbar select{max-width:none;width:100%}.groupbar button{min-height:40px}.controls{gap:7px}.controls label{font-size:12px}.sim-groups{grid-template-columns:1fr}.sim-subpanel.manual{grid-column:auto}.subpanel-controls{grid-template-columns:1fr;gap:8px;padding:10px}.subpanel-controls>label:not(.switch){grid-template-columns:minmax(0,1fr) minmax(100px,46%)}.manual-controls .sim-hint{grid-column:auto}.sim-result{grid-template-columns:repeat(2,minmax(0,1fr))}.sim-result .sim-wide{grid-column:span 2}.annotation-controls{align-items:stretch}.annotation-controls>*{flex:1 1 100%;margin-left:0}.annotation-controls button{min-height:40px}}@media(max-width:1000px){header{align-items:flex-start;flex-direction:column}.summary{grid-template-columns:repeat(3,1fr)}.chart-panel{height:400px}.sim-result{grid-template-columns:repeat(3,minmax(0,1fr))}}
