<body>
<header>
  <div style="display:flex;gap:10px;align-items:center"><h1>A18_2 · K線波段轉折觀察</h1><span class="tag">LIVE / HISTORY</span></div>
  <form id="controls" class="controls"><span class="section-no">1</span>
    <label>股票 <input id="symbol" value="2330" maxlength="12"></label>
    <button type="button" id="prevDay">← 上一日</button>
    <label>日期 <input id="date" type="date"> <strong id="weekday" style="color:var(--text)">—</strong></label>
    <button type="button" id="nextDay">下一日 →</button>
    <label>K線 <select id="interval"><option value="1">1秒</option><option value="5" selected>5秒</option><option value="60">1分</option><option value="300">5分</option></select></label>
    <label>反轉 <select id="threshold"><option value="0.003">0.3%</option><option value="0.005">0.5%</option><option value="0.008">0.8%</option><option value="0.01" selected>1.0%</option><option value="0.015">1.5%</option><option value="0.02">2.0%</option></select></label>
    <label class="switch" title="以當日開盤為 0%，將加權指數 IX0001 疊加在主圖"><input id="overlay" type="checkbox"><span class="slider"></span><span>加權指數</span></label>
    <label class="switch" title="將目前日期之前的 N 個交易日一起接續畫在 K 線圖"><input id="multiDay" type="checkbox"><span class="slider"></span><span>多日</span></label>
    <label class="switch" title="隱藏所選交易日尚未揭露的 K 棒與所有圖上標記"><input id="lookaheadMask" type="checkbox"><span class="slider"></span><span>防偷看</span></label><span id="maskIndicator" class="mask-indicator" hidden>揭露至 —</span>
    <label id="lookbackWrap">往前 <input id="lookbackDays" type="number" min="1" max="20" value="1" style="width:58px"> 個交易日</label>
    <button type="submit">載入 / 更新</button>
    <label><input id="auto" type="checkbox" checked> 5秒自動更新</label>
    <label class="switch" title="顯示各功能區塊的數字編號"><input id="showSectionNumbers" type="checkbox" checked><span class="slider"></span><span>區塊編號</span></label>
  </form>
</header>
<main>
  <section class="summary"><span class="section-no">3</span>
    <div><span>股票</span><strong id="sSymbol">—</strong></div>
    <div><span>日期</span><strong id="sDate">—</strong></div>
    <div><span>最新價</span><strong id="sPrice">—</strong></div>
    <div><span>K棒數</span><strong id="sBars">—</strong></div>
    <div><span>已確認轉折</span><strong id="sTurns">—</strong></div>
    <div><span>候選轉折</span><strong id="sCandidate" class="candidate">—</strong></div>
    <div><span>資料狀態</span><strong id="sState">—</strong></div>
  </section>
<section class="groupbar"><span class="section-no">2</span>
  <div class="group-row group-row-main"><button type="button" id="prevGroup">← 群</button><label>群組 <select id="groupSelect"><option value="">未選群組</option></select></label><button type="button" id="nextGroup">群 →</button></div>
  <div class="group-row"><button type="button" id="prevMember">← 股</button><label>群內個股 <select id="memberSelect"><option value="">—</option></select></label><button type="button" id="nextMember">股 →</button></div>
  <button type="button" id="manageGroups">管理群組</button>
</section>
<div id="groupModal" class="modal"><div class="modal-card"><h2 style="margin-top:0">群組管理</h2><div style="display:flex;gap:8px"><input id="newGroupName" placeholder="新群組名稱" style="flex:1"><button type="button" id="addGroup">新增群組</button></div><hr style="border-color:#27364b"><label>編輯群組 <select id="editGroup"></select></label><button type="button" id="deleteGroup">刪除此群組</button><div style="display:flex;gap:8px;margin-top:12px"><input id="newMemberSymbol" placeholder="股票代號，例如 2330" style="flex:1"><button type="button" id="addMember">加入個股</button></div><div id="memberList" style="margin-top:10px"></div><div style="text-align:right;margin-top:14px"><button type="button" id="closeGroups">完成</button></div></div></div>
  <p id="status">準備載入。</p>
  <div class="trade-workspace"><section class="panel sim-panel" aria-labelledby="strategySimulationTitle">
    <div class="sim-panel-head"><span class="section-no">4</span><h2 id="strategySimulationTitle">策略與手動試算</h2></div>
    <div class="sim-groups">
      <details class="sim-subpanel" open>
        <summary>策略 LONG</summary>
        <div class="subpanel-controls">
          <label class="switch" title="進場規則不變；僅分析"><input id="autoStrategyA" type="checkbox"><span class="slider"></span><span>策略A LONG</span></label><label>A停損% <input id="autoAStopPct" type="number" min="0" step="0.1" value="1"></label><label>A固定移動% <input id="autoATrailPct" type="number" min="0" step="0.1" value="0.5"></label><label>A模式 <select id="autoATrailMode"><option value="FIXED">固定%</option><option value="ATR">ATR動態</option><option value="MAX_FIXED_ATR">固定/ATR取大</option><option value="SIGMA">標準差σ</option><option value="REBOUND_QUANTILE">反彈分位</option></select></label><label>動態來源週期 <select id="autoASourceIntervalSeconds"><option value="1">1秒</option><option value="5">5秒</option><option value="15">15秒</option><option value="30">30秒</option><option value="60">60秒</option></select></label><label>A回看 <input id="autoALookback" type="number" min="2" max="500" value="20"></label><label>A倍數 <input id="autoAMultiplier" type="number" min="0" step="0.1" value="1.5"></label><label>A分位% <input id="autoAQuantile" type="number" min="0" max="100" step="1" value="80"></label><label>A確認 <select id="autoAConfirmation"><option value="NONE">不確認</option><option value="VOLUME">放量</option><option value="STRUCTURE">結構突破</option><option value="VOLUME_OR_STRUCTURE">放量或結構</option></select></label><label>A量倍 <input id="autoAVolumeMultiplier" type="number" min="0" step="0.1" value="1.5"></label>
        </div>
        <p class="auto-note">動態值只看目前 K 前已完成資料；確認只限制移動出場</p>
      </details>
      <details class="sim-subpanel" open>
        <summary>策略 SHORT</summary>
        <div class="subpanel-controls">
          <label class="switch" title="進場規則不變；僅分析"><input id="autoStrategyB" type="checkbox"><span class="slider"></span><span>策略B SHORT</span></label><label>B停損% <input id="autoBStopPct" type="number" min="0" step="0.1" value="0.7"></label><label>B固定移動% <input id="autoBTrailPct" type="number" min="0" step="0.1" value="1"></label><label>B模式 <select id="autoBTrailMode"><option value="FIXED">固定%</option><option value="ATR">ATR動態</option><option value="MAX_FIXED_ATR">固定/ATR取大</option><option value="SIGMA">標準差σ</option><option value="REBOUND_QUANTILE">反彈分位</option></select></label><label>動態來源週期 <select id="autoBSourceIntervalSeconds"><option value="1">1秒</option><option value="5">5秒</option><option value="15">15秒</option><option value="30">30秒</option><option value="60">60秒</option></select></label><label>B回看 <input id="autoBLookback" type="number" min="2" max="500" value="20"></label><label>B倍數 <input id="autoBMultiplier" type="number" min="0" step="0.1" value="1.5"></label><label>B分位% <input id="autoBQuantile" type="number" min="0" max="100" step="1" value="80"></label><label>B確認 <select id="autoBConfirmation"><option value="NONE">不確認</option><option value="VOLUME">放量</option><option value="STRUCTURE">結構突破</option><option value="VOLUME_OR_STRUCTURE">放量或結構</option></select></label><label>B量倍 <input id="autoBVolumeMultiplier" type="number" min="0" step="0.1" value="1.5"></label>
        </div>
        <p class="auto-note">動態值只看目前 K 前已完成資料；確認只限制移動出場</p>
      </details>
      <details class="sim-subpanel manual" open>
        <summary>手動試算</summary>
        <div class="subpanel-controls manual-controls">
          <label class="switch" title="啟用後點擊 K 線選擇進場棒"><input id="simSelect" type="checkbox"><span class="slider"></span><span>選擇進場</span></label>
          <label>方向 <select id="simDirection"><option value="LONG">LONG 多單</option><option value="SHORT">SHORT 空單</option></select></label>
          <label>股數 <input id="simQuantity" type="number" min="1" step="1" value="1000"></label>
          <label>稅別 <select id="simTaxMode"><option value="DAYTRADE">DAYTRADE 當沖</option><option value="NORMAL">NORMAL 一般</option></select></label>
          <label>手續費率 % <input id="simFeeRate" type="number" min="0" step="0.0001" value="0.0855"></label>
          <label>最低手續費 <input id="simMinFee" type="number" min="0" step="1" value="20"></label>
          <label>固定停損 % <input id="simStopPct" type="number" min="0" step="0.1" value="1"></label>
          <label>固定移動 % <input id="simTrailPct" type="number" min="0" step="0.1" value="1.5"></label>
          <label title="ATR=真實波幅；固定/ATR取大=兩者取較寬；標準差σ=來源週期報酬波動；反彈分位=近期不利振幅分位">移動模式 <select id="simTrailMode"><option value="FIXED">固定%</option><option value="ATR">ATR動態</option><option value="MAX_FIXED_ATR">固定/ATR取大</option><option value="SIGMA">標準差σ</option><option value="REBOUND_QUANTILE">反彈分位</option></select></label>
          <label>動態來源週期 <select id="simSourceIntervalSeconds"><option value="1">1秒</option><option value="5">5秒</option><option value="15">15秒</option><option value="30">30秒</option><option value="60">60秒</option></select></label>
          <label>回看K <input id="simLookback" type="number" min="2" max="500" value="20"></label><label>倍數 <input id="simMultiplier" type="number" min="0" step="0.1" value="1.5"></label><label>分位% <input id="simQuantile" type="number" min="0" max="100" step="1" value="80"></label>
          <label title="只限制移動出場；固定停損不等待確認">移動確認 <select id="simConfirmation"><option value="NONE">不確認</option><option value="VOLUME">放量</option><option value="STRUCTURE">結構突破</option><option value="VOLUME_OR_STRUCTURE">放量或結構</option></select></label><label>量倍 <input id="simVolumeMultiplier" type="number" min="0" step="0.1" value="1.5"></label>
          <button type="button" id="simClear">清除進場</button><span id="simHint" class="sim-hint">開啟「選擇進場」後點擊 K 線</span>
        </div>
        <div id="simResult" class="sim-result"><div class="sim-empty">尚未選擇進場 K 棒。</div></div>
      </details>
    </div>
  </section>
  <section class="panel live-panel" aria-labelledby="liveOrderTitle">
    <div class="live-head"><span class="section-no">真</span><h2 id="liveOrderTitle">真單區 · A18_21</h2><span id="runtimeHealthBadge" class="runtime-badge runtime-warn">健康檢查中</span><span id="runtimeControlBadge" class="runtime-badge runtime-warn">交易控制檢查中</span></div>
    <p class="live-warning">真單出場由 A18_21 即時行情引擎執行；固定%、ATR、固定/ATR取大、σ、反彈分位與放量／結構確認都會隨真單參數送出。</p>
