</main>
<script>
(()=>{'use strict';const $=id=>document.getElementById(id);const liveSessionKey='a18_2.swing.runtime21.activeEntryId';const state={bars:[],sourceBucketCache:{},indexBars:[],turns:[],candidate:null,timer:null,hoverIndex:null,geometry:null,dayRanges:[],simEntryTime:null,simulation:null,autoTrades:[],annotations:[],annotationBar:null,annotationId:null,maskEnabled:false,revealThroughMs:null,maskResetPending:false,maskDragging:false,maskDragged:false,maskFrame:null,runtimeHealth:null,runtimeControl:null,runtimeReachable:false,liveHistoryReachable:false,livePollBusy:false,activeEntryId:sessionStorage.getItem(liveSessionKey)||null,liveEntry:null,liveTakeover:null,liveEntries:[],liveDecisions:[],liveAllDecisions:[],liveOrders:[]};
const fmtP=n=>Number(n).toLocaleString('zh-TW',{maximumFractionDigits:4});const fmtT=s=>new Date(s).toLocaleTimeString('zh-TW',{hour12:false,hour:'2-digit',minute:'2-digit',second:'2-digit'});
const fmtMoney=n=>Math.trunc(Number(n)).toLocaleString('zh-TW');
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
async function liveJson(url,options){const r=await fetch(url,{cache:'no-store',...options});let body=null;try{body=await r.json()}catch{body={error:`HTTP ${r.status}`}}if(!r.ok){const e=new Error(body?.error||body?.title||`HTTP ${r.status}`);e.status=r.status;throw e}return body}
function setRuntimeBadges(){const h=$('runtimeHealthBadge'),c=$('runtimeControlBadge');if(!state.runtimeReachable){h.textContent='A18_21 無法連線';h.className='runtime-badge runtime-bad'}else{const real=state.runtimeHealth?.enableBrokerExecution&&state.runtimeHealth?.enableRealOrders;h.textContent=`A18_21 ${state.runtimeHealth?.status||'OK'} · ${real?'REAL 已啟用':'REAL 未啟用'}`;h.className=`runtime-badge ${real?'runtime-ok':'runtime-warn'}`}if(!state.runtimeControl){c.textContent='交易控制未知';c.className='runtime-badge runtime-bad'}else if(state.runtimeControl.blocked){c.textContent='交易已封鎖';c.className='runtime-badge runtime-bad'}else{c.textContent='交易控制未封鎖';c.className='runtime-badge runtime-ok'}}
function livePlanSymbol(p){return String(p?.symbol||p?.symbolOrName||'').trim().toUpperCase()}
function livePlanOpen(p){return ['pending','submitted'].includes(String(p?.status||'').toLowerCase())}
function openLivePlanForCurrentSymbol(){const symbol=$('symbol').value.trim().toUpperCase();return(state.liveEntries||[]).find(p=>livePlanSymbol(p)===symbol&&livePlanOpen(p))}
function liveEligibility(){let reason='可送出：將以目前方向、股數與出場參數建立 ImmediateMarket 真單進場計畫。',ok=true;const qty=Number($('simQuantity').value),direction=$('simDirection').value,sourceSeconds=sourceInterval($('simSourceIntervalSeconds').value),taipeiToday=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),realEnabled=state.runtimeHealth?.brokerProvider==='Yuanta'&&state.runtimeHealth?.enableBrokerExecution===true&&state.runtimeHealth?.enableRealOrders===true,advancedNeeded=$('simTrailMode').value!=='FIXED'||$('simConfirmation').value!=='NONE'||sourceSeconds!==1,supportedSourceIntervals=Array.isArray(state.runtimeHealth?.trailingSourceIntervalsSeconds)?state.runtimeHealth.trailingSourceIntervalsSeconds.map(Number):[],openPlan=openLivePlanForCurrentSymbol();if($('date').value!==taipeiToday){ok=false;reason=`真單只允許目前交易日 ${taipeiToday}；歷史日期禁止送 ImmediateMarket 真單。`}else if(!['LONG','SHORT'].includes(direction)||!Number.isInteger(qty)||qty<=0){ok=false;reason='方向與股數必須有效。'}else if(!state.runtimeReachable){ok=false;reason='A18_21 健康或交易控制狀態無法取得，禁止送單。'}else if(!state.liveHistoryReachable){ok=false;reason='A18_21 計畫歷史無法取得，為避免重複送單目前禁止建立新計畫。'}else if(advancedNeeded&&state.runtimeHealth?.advancedTrailing!==true){ok=false;reason='A18_21 未宣告 advancedTrailing capability，禁止送出進階 trailing 真單。'}else if(sourceSeconds!==1&&!supportedSourceIntervals.includes(sourceSeconds)){ok=false;reason=`A18_21 未宣告支援 ${sourceSeconds} 秒 trailing 來源週期，為避免歷史/真單語意不一致目前禁止送單。`}else if(!realEnabled){ok=false;reason='A18_21 目前不是 Yuanta REAL 可執行狀態，禁止以真單按鈕建立計畫。'}else if(state.runtimeControl?.blocked){ok=false;reason='A18_21 kill-switch／交易控制目前封鎖，禁止送單。'}else if(openPlan){ok=false;reason=`此股票仍有 ${openPlan.status} 計畫 ${openPlan.id}，隱藏卡片不會允許重複送單。`}$('liveEligibility').textContent=reason;$('liveSend').disabled=!ok;return ok}
function renderLive(){const p=state.liveEntry,t=state.liveTakeover,ds=state.liveDecisions||[];if(!p){$('liveStatus').innerHTML='<div class="sim-empty">本頁工作階段尚無 A18_21 進場計畫（歷史成交標記仍會顯示）。</div>';$('liveDelete').disabled=true;$('liveHide').disabled=true;$('liveDecisions').textContent='尚無目前卡片的決策事件。';$('liveOrderReport').textContent='尚無目前卡片的券商委託回報。';liveEligibility();drawLiveMarkers();return}const rs=t?.ruleState||{};$('liveStatus').innerHTML=`<div><span>計畫狀態</span><strong>${esc(p.status)}</strong></div><div><span>Plan ID</span><strong>${esc(p.id)}</strong></div><div><span>券商單號</span><strong>${esc(p.brokerOrderNo||'—')}</strong></div><div><span>實際均價／成交股數</span><strong>${p.averageFillPrice>0?fmtP(p.averageFillPrice):'—'}／${Number(p.filledQuantityShares||0).toLocaleString('zh-TW')}</strong></div><div><span>Takeover ID／狀態</span><strong>${esc(p.takeoverId||'—')}／${esc(t?.status||'—')}</strong></div><div><span>接管水位（高／低）</span><strong>${rs.highWaterPrice==null?'—':fmtP(rs.highWaterPrice)}／${rs.lowWaterPrice==null?'—':fmtP(rs.lowWaterPrice)}</strong></div><div><span>即時 trailing</span><strong>${rs.effectiveTrailingPercent==null?'—':Number(rs.effectiveTrailingPercent).toFixed(3)+'%'}／${rs.trailingThresholdPrice==null?'—':fmtP(rs.trailingThresholdPrice)}${rs.trailingConfirmationPassed==null?'':`／${rs.trailingConfirmationPassed?'確認✓':'等待確認'}`}</strong></div><div><span>最後錯誤</span><strong>${esc(p.lastError||'—')}</strong></div><div><span>最後更新</span><strong>${esc(p.updatedAt?new Date(p.updatedAt).toLocaleString('zh-TW'):'—')}</strong></div>`;$('liveDelete').disabled=String(p.status).toLowerCase()!=='pending';$('liveHide').disabled=String(p.status).toLowerCase()==='pending';const latest=ds[0];$('liveDecisions').textContent=ds.length?ds.slice(0,12).map(d=>`${new Date(d.occurredAt).toLocaleString('zh-TW')} | ${d.outcome} | ${d.rule} | ${d.code}\n${d.message||''}${d.brokerOrderNo?` | order ${d.brokerOrderNo}`:''}`).join('\n\n'):'尚無決策事件。';const orderNos=new Set([p.brokerOrderNo,...ds.map(d=>d.brokerOrderNo)].filter(Boolean).map(x=>String(x).toLowerCase())),related=(state.liveOrders||[]).filter(o=>orderNos.has(String(o.orderNo||o.brokerOrderNo||'').toLowerCase()));$('liveOrderReport').textContent=related.length?JSON.stringify(related,null,2):latest?`最新決策：${latest.outcome} / ${latest.code} / ${latest.message||''}\n尚未匹配到券商委託回報。`:'尚無相關券商委託回報。';liveEligibility();drawLiveMarkers()}
async function pollRuntime21(){if(state.livePollBusy)return;state.livePollBusy=true;try{const [health,control,entries,orders,decisions]=await Promise.allSettled([liveJson('/api/runtime21/health'),liveJson('/api/runtime21/trading-control'),liveJson('/api/runtime21/entries'),liveJson('/api/runtime21/orders'),liveJson('/api/runtime21/decisions?limit=1000')]);state.runtimeHealth=health.status==='fulfilled'?health.value:null;state.runtimeControl=control.status==='fulfilled'?control.value:null;state.runtimeReachable=health.status==='fulfilled'&&control.status==='fulfilled';state.liveHistoryReachable=entries.status==='fulfilled'&&Array.isArray(entries.value);if(state.liveHistoryReachable)state.liveEntries=entries.value;if(orders.status==='fulfilled'&&Array.isArray(orders.value))state.liveOrders=orders.value;if(decisions.status==='fulfilled'&&Array.isArray(decisions.value))state.liveAllDecisions=decisions.value.sort((a,b)=>new Date(b.occurredAt)-new Date(a.occurredAt));setRuntimeBadges();if(state.activeEntryId){const p=state.liveEntries.find(x=>String(x.id).toLowerCase()===String(state.activeEntryId).toLowerCase());if(p){state.liveEntry=p;state.liveDecisions=p.takeoverId?state.liveAllDecisions.filter(d=>String(d.takeoverId).toLowerCase()===String(p.takeoverId).toLowerCase()):[];if(p.takeoverId){try{state.liveTakeover=await liveJson(`/api/runtime21/takeovers/${encodeURIComponent(p.takeoverId)}`)}catch{state.liveTakeover=null}}else state.liveTakeover=null}else if(state.liveHistoryReachable){state.activeEntryId=null;state.liveEntry=null;state.liveTakeover=null;state.liveDecisions=[];sessionStorage.removeItem(liveSessionKey)}}else{state.liveEntry=null;state.liveTakeover=null;state.liveDecisions=[]}renderLive()}finally{state.livePollBusy=false}}
function liveReferenceBar(){const day=$('date').value,rows=revealedBars().filter(b=>String(b.startTime).slice(0,10)===day);return rows.length?rows[rows.length-1]:null}
function createLivePayload(){const stop=Math.max(0,Number($('simStopPct').value)||0),trail=Math.max(0,Number($('simTrailPct').value)||0),reference=liveReferenceBar(),modeMap={FIXED:'Fixed',ATR:'Atr',MAX_FIXED_ATR:'MaxFixedAtr',SIGMA:'Sigma',REBOUND_QUANTILE:'ReboundQuantile'},confirmMap={NONE:'None',VOLUME:'Volume',STRUCTURE:'Structure',VOLUME_OR_STRUCTURE:'VolumeOrStructure'},symbol=$('symbol').value.trim().toUpperCase(),referenceNote=reference?`; referenceTime=${reference.startTime}; referenceClose=${reference.close}`:'';return{symbolOrName:symbol,direction:$('simDirection').value==='LONG'?'Long':'Short',quantityShares:Number($('simQuantity').value),entry:{type:'ImmediateMarket',triggerPrice:0,triggerDirection:'AtOrBelow'},exitRules:{fixedForceExit:{enabled:false,price:0},adverseStopLoss:{enabled:stop>0,percent:stop},positionLossStop:{enabled:false,amountTwd:0},trailingExit:{enabled:trail>0,percent:trail,mode:modeMap[$('simTrailMode').value]||'Fixed',sourceIntervalSeconds:sourceInterval($('simSourceIntervalSeconds').value),lookback:Math.max(2,Math.min(500,Number($('simLookback').value)||20)),multiplier:Math.max(0,Number($('simMultiplier').value)||0),quantile:Math.max(0,Math.min(100,Number($('simQuantile').value)||80)),confirmation:confirmMap[$('simConfirmation').value]||'None',volumeMultiplier:Math.max(0,Number($('simVolumeMultiplier').value)||0)},periodicTrade:{enabled:false,action:'Buy',intervalSeconds:60,quantity:0},forcedExitTime:{enabled:false,time:'00:00:00'},adverseStepTrade:{enabled:false,everyTwd:0,quantity:0,mode:'Add'}},exitTradingBudgetTwd:0,note:`source=A18_2 swing; symbol=${symbol}; selectedDate=${$('date').value}${referenceNote}`}}
async function sendLiveOrder(){if(!liveEligibility())return;const p=createLivePayload(),stop=p.exitRules.adverseStopLoss.enabled?`${p.exitRules.adverseStopLoss.percent}%`:'停用',tr=p.exitRules.trailingExit,trail=tr.enabled?`${tr.mode} / 來源${tr.sourceIntervalSeconds}秒 / ${tr.percent}% / 回看${tr.lookback} / 倍數${tr.multiplier} / ${tr.confirmation}`:'停用',reference=liveReferenceBar();if(!confirm(`即將透過 A18_21 建立真單進場計畫\n\n股票：${p.symbolOrName}\n方向：${p.direction}\n股數：${p.quantityShares}\n停損：${stop}\n移動出場：${trail}\n最新可見 K 收盤參考：${reference?fmtP(reference.close):'—'}（僅供參考）\n\n警告：若 A18_21 runtime 已啟用交易，這會送出 REAL 真實委託。是否繼續？`))return;$('liveSend').disabled=true;try{const row=await liveJson('/api/runtime21/entries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});state.activeEntryId=row.id;sessionStorage.setItem(liveSessionKey,row.id);state.liveEntry=row;state.liveEntries=[row,...state.liveEntries.filter(x=>String(x.id).toLowerCase()!==String(row.id).toLowerCase())];await pollRuntime21()}catch(e){$('liveDecisions').textContent=`建立真單計畫失敗：${e.message}`;liveEligibility()}}
async function deleteLivePending(){const p=state.liveEntry;if(!p||String(p.status).toLowerCase()!=='pending'||!confirm(`將永久刪除尚未送出的 Pending 計畫 ${p.id}，確定？`))return;$('liveDelete').disabled=true;try{await liveJson(`/api/runtime21/entries/${encodeURIComponent(p.id)}`,{method:'DELETE'});state.activeEntryId=null;state.liveEntry=null;state.liveTakeover=null;state.liveDecisions=[];sessionStorage.removeItem(liveSessionKey);await pollRuntime21()}catch(e){$('liveDecisions').textContent=`刪除失敗：${e.message}`;renderLive()}}
function hideLiveCard(){const p=state.liveEntry;if(!p||String(p.status).toLowerCase()==='pending')return;state.activeEntryId=null;state.liveEntry=null;state.liveTakeover=null;state.liveDecisions=[];sessionStorage.removeItem(liveSessionKey);renderLive()}
function liveOrderNo(x){return String(x?.orderNo||x?.brokerOrderNo||'').trim().toLowerCase()}
function liveReportSymbol(o){return String(o?.symbol||o?.symbolOrName||o?.stockNo||o?.stockCode||'').trim().toUpperCase()}
function liveOrderTime(o){const rawDate=String(o?.orderDate||'').trim(),rawTime=String(o?.orderTime||'').trim();if(rawDate){const dateDigits=rawDate.replace(/\D/g,''),day=dateDigits.length>=8?`${dateDigits.slice(0,4)}-${dateDigits.slice(4,6)}-${dateDigits.slice(6,8)}`:rawDate.replace(/[/.]/g,'-').slice(0,10);let clock='00:00:00';if(rawTime){const timeDigits=rawTime.replace(/\D/g,'').padStart(6,'0');clock=rawTime.includes(':')?rawTime.slice(0,8):`${timeDigits.slice(0,2)}:${timeDigits.slice(2,4)}:${timeDigits.slice(4,6)}`}const combined=`${day}T${clock}+08:00`;if(Number.isFinite(new Date(combined).getTime()))return combined}return o?.filledAt||o?.lastFillAt||o?.reportedAt||o?.lastUpdatedAt||o?.updatedAt||o?.exchangeAt||o?.occurredAt||o?.timestamp||o?.createdAt||null}
function taipeiDateOf(value){const d=new Date(value);return Number.isFinite(d.getTime())?new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(d):''}
function liveBarIndex(time){const target=new Date(time).getTime(),day=taipeiDateOf(time);if(!Number.isFinite(target))return-1;let best=-1,dist=Infinity;for(let i=0;i<state.bars.length;i++){if(String(state.bars[i].startTime).slice(0,10)!==day)continue;const d=Math.abs(new Date(state.bars[i].startTime).getTime()-target);if(d<dist){dist=d;best=i}}return best}
function drawLiveMarkers(){const cv=$('liveChart'),base=$('chart'),r=base.getBoundingClientRect(),dpr=devicePixelRatio||1;cv.width=Math.max(1,r.width*dpr);cv.height=Math.max(1,r.height*dpr);const c=cv.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,r.width,r.height);const g=state.geometry,symbol=$('symbol').value.trim().toUpperCase(),day=$('date').value;if(!g||!symbol)return;const plans=(state.liveEntries||[]).filter(p=>livePlanSymbol(p)===symbol),entryNos=new Set(plans.map(p=>String(p?.brokerOrderNo||'').trim().toLowerCase()).filter(Boolean)),takeoverIds=new Set(plans.map(p=>String(p.takeoverId||'').trim().toLowerCase()).filter(Boolean)),exitNos=new Set((state.liveAllDecisions||[]).filter(d=>String(d?.outcome||'').toLowerCase()==='submitted'&&takeoverIds.has(String(d?.takeoverId||'').trim().toLowerCase())).map(d=>String(d?.brokerOrderNo||'').trim().toLowerCase()).filter(Boolean)),marks=[],seen=new Set();for(const o of state.liveOrders||[]){const no=liveOrderNo(o),reportSymbol=liveReportSymbol(o),kind=entryNos.has(no)?'entry':exitNos.has(no)?'exit':null,quantity=Number(o.filledQuantity??o.filledQuantityShares??0),price=Number(o.averageFillPrice??0),time=liveOrderTime(o);if(!kind||!no||(reportSymbol&&reportSymbol!==symbol)||quantity<=0||price<=0||!time||taipeiDateOf(time)!==day)continue;const i=liveBarIndex(time),key=`${kind}|${no}|${time}|${price}`;if(i>=0&&isBarRevealed(i)&&!seen.has(key)){seen.add(key);marks.push({i,time,price,color:kind==='entry'?'#ffb347':'#ff7bd5',label:`${kind==='entry'?'真進':'真出'} ${fmtP(price)} × ${quantity.toLocaleString('zh-TW')}`})}}for(const m of marks){const px=g.p.l+(m.i+.5)*g.cw,py=g.y(m.price);c.fillStyle=m.color;c.strokeStyle='#341b05';c.lineWidth=2;c.beginPath();c.moveTo(px,py-7);c.lineTo(px+7,py+6);c.lineTo(px-7,py+6);c.closePath();c.fill();c.stroke();c.font='bold 11px system-ui';c.fillStyle=m.color;c.fillText(m.label,Math.min(g.w-150,px+9),Math.max(g.p.t+12,py-8))}}
const barMs=b=>new Date(b?.startTime).getTime(),selectedDay=()=>$('date').value,intervalMs=()=>Math.max(1,+$('interval').value||1)*1000;
function selectedDayBars(){const day=selectedDay();return state.bars.filter(b=>String(b.startTime).slice(0,10)===day)}
function isTimeRevealed(time){if(!state.maskEnabled)return true;const day=String(time||'').slice(0,10),selected=selectedDay();if(day<selected)return true;if(day>selected)return false;const ms=new Date(time).getTime();return Number.isFinite(ms)&&Number.isFinite(state.revealThroughMs)&&ms<state.revealThroughMs}
function isBarRevealed(i){return i>=0&&i<state.bars.length&&isTimeRevealed(state.bars[i].startTime)}
function revealedBars(){return state.maskEnabled?state.bars.filter(b=>isTimeRevealed(b.startTime)):state.bars}
function resetRevealBoundary(){const dayBars=selectedDayBars();state.revealThroughMs=dayBars.length?Math.min(barMs(dayBars[0])+60000,barMs(dayBars.at(-1))+intervalMs()):null;updateMaskIndicator()}
function updateMaskIndicator(){const el=$('maskIndicator');el.hidden=!state.maskEnabled;el.textContent=state.maskEnabled&&Number.isFinite(state.revealThroughMs)?`揭露至 ${fmtT(new Date(state.revealThroughMs))}`:'揭露至 —'}
function maskBoundaryIndex(){if(!state.maskEnabled)return-1;let last=-1;for(let i=0;i<state.bars.length;i++)if(isBarRevealed(i))last=i;return last}
function maskBoundaryX(){const g=state.geometry;if(!g)return null;const last=maskBoundaryIndex();return Math.max(g.p.l,Math.min(g.w-g.p.r,g.p.l+(last+1)*g.cw))}
function scheduleMaskRedraw(){if(state.maskFrame!=null)return;state.maskFrame=requestAnimationFrame(()=>{state.maskFrame=null;renderAnnotations();draw();drawHover()})}
