function drawAnnotationMarkers(){const cv=$('annotationChart'),base=$('chart'),r=base.getBoundingClientRect(),dpr=devicePixelRatio||1;cv.width=Math.max(1,r.width*dpr);cv.height=Math.max(1,r.height*dpr);const c=cv.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,r.width,r.height);const g=state.geometry;if(!g)return;c.save();for(const a of state.annotations||[]){if(!isTimeRevealed(a.barTime))continue;const i=annotationBarIndex(a.barTime);if(i<0||!isBarRevealed(i))continue;const x=g.p.l+(i+.5)*g.cw,y=g.y(Number(a.price)),m=annotationMeta(a.label);c.fillStyle=m.color;c.strokeStyle='#08111d';c.lineWidth=2;c.beginPath();c.moveTo(x,y-9);c.lineTo(x+8,y+5);c.lineTo(x-8,y+5);c.closePath();c.fill();c.stroke();c.font='bold 11px system-ui';c.fillStyle=m.color;c.fillText(`${m.code} ${fmtP(a.price)}`,Math.min(g.w-95,x+9),Math.max(g.p.t+12,y-9))}c.restore()}
const trailModes=['FIXED','ATR','MAX_FIXED_ATR','SIGMA','REBOUND_QUANTILE'],confirmModes=['NONE','VOLUME','STRUCTURE','VOLUME_OR_STRUCTURE'],sourceIntervals=[1,5,15,30,60];
