function trailConfig(prefix){const value=(suffix,fallback)=>$(prefix+suffix)?.value??fallback;return{mode:trailModes.includes(value('TrailMode','FIXED'))?value('TrailMode','FIXED'):'FIXED',trailPct:Math.max(0,+value('TrailPct',0)||0)/100,sourceIntervalSeconds:sourceInterval(value('SourceIntervalSeconds',1)),lookback:Math.max(2,Math.min(500,Math.trunc(+value('Lookback',20)||20))),multiplier:Math.max(0,+value('Multiplier',1.5)||0),quantile:Math.max(0,Math.min(100,+value('Quantile',80)||0)),confirmation:confirmModes.includes(value('Confirmation','NONE'))?value('Confirmation','NONE'):'NONE',volumeMultiplier:Math.max(0,+value('VolumeMultiplier',1.5)||0)}}
function simParams(){return{direction:$('simDirection').value,quantity:Math.max(1,Math.trunc(+$('simQuantity').value||1)),taxMode:$('simTaxMode').value,feeRate:Math.max(0,+$('simFeeRate').value||0)/100,minFee:Math.max(0,+$('simMinFee').value||0),stopPct:Math.max(0,+$('simStopPct').value||0)/100,...trailConfig('sim')}}
function quantile(values,pct){if(!values.length)return null;const a=[...values].sort((a,b)=>a-b),x=(a.length-1)*pct/100,lo=Math.floor(x),hi=Math.ceil(x);return a[lo]+(a[hi]-a[lo])*(x-lo)}
const tradeDate=b=>String(b?.startTime||'').slice(0,10);
function sourceBucketSeries(seconds){const interval=sourceInterval(seconds),cached=state.sourceBucketCache[interval];if(cached?.bars===state.bars)return cached;const width=interval*1000,buckets=[],barBucketIndexes=[];for(let j=0;j<state.bars.length;j++){const b=state.bars[j],day=tradeDate(b),ms=new Date(b.startTime).getTime(),start=Math.floor(ms/width)*width;let bucket=buckets.at(-1);if(!Number.isFinite(start)){barBucketIndexes[j]=-1;continue}if(!bucket||bucket.bucketStart!==start||bucket.day!==day){bucket={bucketStart:start,day,startTime:b.startTime,firstIndex:j,lastIndex:j,open:Number(b.open),high:Number(b.high),low:Number(b.low),close:Number(b.close),volume:Number(b.volume||0),tickCount:Number(b.tickCount||0)};buckets.push(bucket)}else{bucket.lastIndex=j;bucket.high=Math.max(bucket.high,Number(b.high));bucket.low=Math.min(bucket.low,Number(b.low));bucket.close=Number(b.close);bucket.volume+=Number(b.volume||0);bucket.tickCount+=Number(b.tickCount||0)}barBucketIndexes[j]=buckets.length-1}const series={bars:state.bars,buckets,barBucketIndexes};state.sourceBucketCache[interval]=series;return series}
function sourceBucketContext(i,seconds){const series=sourceBucketSeries(seconds),bucketIndex=series.barBucketIndexes[i],full=series.buckets[bucketIndex];if(!full)return{completed:[],current:null};const completed=[];for(let k=bucketIndex-1;k>=0&&series.buckets[k].day===full.day;k--)completed.push(series.buckets[k]);completed.reverse();const current={...full,high:-Infinity,low:Infinity,close:Number(state.bars[i].close),volume:0,tickCount:0,lastIndex:i};for(let j=full.firstIndex;j<=i;j++){const b=state.bars[j];current.high=Math.max(current.high,Number(b.high));current.low=Math.min(current.low,Number(b.low));current.volume+=Number(b.volume||0);current.tickCount+=Number(b.tickCount||0)}return{completed,current}}
