function trailConfirmed(i,direction,cfg,hist,current){if(cfg.confirmation==='NONE')return{ok:true,volume:false,structure:false};const b=current||state.bars[i],avg=hist.length?hist.reduce((a,x)=>a+Number(x.volume||0),0)/hist.length:0,volume=hist.length>0&&Number(b.volume||0)>=avg*cfg.volumeMultiplier,structureHist=hist.slice(-Math.min(cfg.lookback,10)),structure=structureHist.length>0&&(direction==='SHORT'?Number(b.high)>=Math.max(...structureHist.map(x=>Number(x.high))):Number(b.low)<=Math.min(...structureHist.map(x=>Number(x.low)))),ok=cfg.confirmation==='VOLUME'?volume:cfg.confirmation==='STRUCTURE'?structure:volume||structure;return{ok,volume,structure}}
function simulateExit(entryIndex,direction,stopPct,cfg,sameDay){const entryBar=state.bars[entryIndex],entryPrice=Number(entryBar.close),day=tradeDate(entryBar),fixed=direction==='LONG'?entryPrice*(1-stopPct):entryPrice*(1+stopPct);let water=entryPrice,exitIndex=-1,exitPrice=0,reason='',trailDetail=`${cfg.mode}｜等待有利水位`,effectiveTrailPct=cfg.trailPct,last=entryIndex;for(let i=entryIndex+1;i<state.bars.length;i++){const b=state.bars[i];if(sameDay&&tradeDate(b)!==day)break;last=i;const fixedHit=direction==='LONG'?Number(b.low)<=fixed:Number(b.high)>=fixed;if(fixedHit){exitIndex=i;exitPrice=fixed;reason='固定停損';trailDetail=`固定停損（移動確認不適用）`;break}const eff=effectiveTrail(i,water,direction,cfg),eligible=direction==='LONG'?water>entryPrice:water<entryPrice,threshold=direction==='LONG'?water-eff.distance:water+eff.distance,trailHit=eligible&&(direction==='LONG'?Number(b.low)<=threshold:Number(b.high)>=threshold),confirmation=trailConfirmed(i,direction,cfg,eff.hist,eff.current);effectiveTrailPct=eff.pct;trailDetail=`${cfg.mode}${eff.fallback?'(資料不足→固定)':''}｜來源${cfg.sourceIntervalSeconds}秒｜${(eff.pct*100).toFixed(3)}% / ${fmtP(eff.distance)}｜確認 ${cfg.confirmation}${cfg.confirmation==='NONE'?'':confirmation.ok?' ✓':' ×'}`;if(trailHit&&confirmation.ok){exitIndex=i;exitPrice=threshold;reason=`${threshold*(direction==='LONG'?1:-1)>entryPrice*(direction==='LONG'?1:-1)?'移動停利':'移動保護'} · ${cfg.mode}`;break}water=direction==='LONG'?Math.max(water,Number(b.high)):Math.min(water,Number(b.low))}const open=exitIndex<0;if(open){exitIndex=last;exitPrice=Number(state.bars[last].close);reason='收盤／資料尾端結算'}return{entryPrice,entryBar,water,exitIndex,exitPrice,reason,trailDetail,effectiveTrailPct,trailMode:cfg.mode,open}}
function addCosts(result,direction,p){const {entryPrice,exitPrice}=result,amount=price=>price*p.quantity,fee=value=>Math.max(Math.trunc(p.minFee),Math.trunc(value*p.feeRate)),taxRate=p.taxMode==='DAYTRADE'?.0015:.003,entryAmount=amount(entryPrice),exitAmount=amount(exitPrice),entryFee=fee(entryAmount),exitFee=fee(exitAmount),tax=Math.trunc((direction==='LONG'?exitAmount:entryAmount)*taxRate),gross=Math.trunc((direction==='LONG'?exitPrice-entryPrice:entryPrice-exitPrice)*p.quantity),net=direction==='LONG'?(exitAmount-exitFee-tax)-(entryAmount+entryFee):(entryAmount-entryFee-tax)-(exitAmount+exitFee),basis=direction==='LONG'?entryAmount+entryFee:entryAmount-entryFee-tax;return{...result,gross,entryFee,exitFee,tax,net:Math.trunc(net),actualReturn:net/Math.abs(basis||entryAmount)*100}}
function autoTradeFrom(entryIndex,direction,strategy){const p=simParams(),prefix=strategy==='A'?'autoA':'autoB',stopPct=Math.max(0,+$(prefix+'StopPct').value||0)/100,cfg=trailConfig(prefix),x=addCosts(simulateExit(entryIndex,direction,stopPct,cfg,true),direction,p);return{...x,strategy,direction,entryIndex,entry:{time:x.entryBar.startTime,price:x.entryPrice},exit:{time:state.bars[x.exitIndex].startTime,price:x.exitPrice}}}
function firstIndexAtOrAfter(startIndex,targetMs){for(let i=Math.max(0,startIndex);i<state.bars.length;i++)if(new Date(state.bars[i].startTime).getTime()>=targetMs)return i;return-1}
function strategyATrades(){const out=[];let i=0;while(i<state.bars.length){const day=String(state.bars[i].startTime).slice(0,10),t=new Date(state.bars[i].startTime).getTime(),j=firstIndexAtOrAfter(i,t+5000);if(j<0||String(state.bars[j].startTime).slice(0,10)!==day)break;const base=Number(state.bars[i].close),jump=Number(state.bars[j].close)/base-1;if(jump<.003){i++;continue}const k=firstIndexAtOrAfter(j,new Date(state.bars[j].startTime).getTime()+5000);if(k<0||String(state.bars[k].startTime).slice(0,10)!==day){i=j+1;continue}const cont=Number(state.bars[k].close)/Number(state.bars[j].close)-1;if(cont<.001){i=j+1;continue}const tr=autoTradeFrom(k,'LONG','A');out.push(tr);i=Math.max(k+1,tr.exitIndex+1)}return out}
