function renderAutoTrades(){const body=$('autoTrades');if(!body)return;if(!$('autoStrategyA').checked&&!$('autoStrategyB').checked){body.innerHTML='<tr><td colspan="9" class="empty">策略 A / B 預設關閉</td></tr>';return}const a=state.autoTrades.filter(t=>isTimeRevealed(t.entry.time)&&isTimeRevealed(t.exit.time));if(!a.length){body.innerHTML='<tr><td colspan="9" class="empty">目前已揭露資料沒有符合條件的自動策略交易</td></tr>';return}body.innerHTML=a.map(t=>`<tr><td class="${t.strategy==='A'?'strategy-a':'strategy-b'}">${t.strategy==='A'?'A 突跳延續':'B 高點爆量反轉'}</td><td>${t.direction}</td><td>${String(t.entry.time).slice(5,10)} ${fmtT(t.entry.time)}</td><td>${fmtP(t.entry.price)}</td><td>${String(t.exit.time).slice(5,10)} ${fmtT(t.exit.time)}</td><td>${fmtP(t.exit.price)}</td><td>${t.reason}</td><td class="${t.net>=0?'up':'down'}">${t.net>=0?'+':''}${fmtMoney(t.net)}</td><td class="${t.actualReturn>=0?'up':'down'}">${t.actualReturn>=0?'+':''}${t.actualReturn.toFixed(3)}%</td></tr>`).join('')}
