function renderSimulation(){const s=state.simulation;if(!state.simEntryTime){$('simResult').innerHTML='<div class="sim-empty">尚未選擇進場 K 棒。</div>';$('simHint').textContent=$('simSelect').checked?'請點擊 K 線選擇進場棒':'開啟「選擇進場」後點擊 K 線';return}if(!s){$('simResult').innerHTML='<div class="sim-empty">選定的進場 K 棒已不在目前資料中，請重新選擇。</div>';return}if(!isTimeRevealed(s.entry.time)||!isTimeRevealed(s.exit.time)){$('simResult').innerHTML='<div class="sim-empty">模擬結果超出目前揭露範圍。</div>';$('simHint').textContent='拖曳防偷看邊界以揭露後續結果';return}const cls=s.net>=0?'sim-positive':'sim-negative',status=s.open?'收盤／資料尾端結算':'已出場',resultText=s.net>=0?'獲利':'虧損';$('simHint').textContent=`${s.direction}｜${status}｜從進場後下一根 K 棒開始模擬`;$('simResult').innerHTML=`<div class="sim-wide"><span>進場時間／價格</span><strong>${String(s.entry.time).slice(0,10)} ${fmtT(s.entry.time)}／${fmtP(s.entry.price)}</strong></div><div class="sim-wide"><span>出場時間／價格</span><strong>${String(s.exit.time).slice(0,10)} ${fmtT(s.exit.time)}／${fmtP(s.exit.price)}</strong></div><div><span>觸發規則</span><strong>${s.reason}</strong></div><div><span>移動模式／有效%</span><strong>${s.trailMode}／${(s.effectiveTrailPct*100).toFixed(3)}%</strong></div><div class="sim-wide"><span>移動距離／確認</span><strong>${s.trailDetail}</strong></div><div><span>${s.direction==='LONG'?'最高水位':'最低水位'}</span><strong>${fmtP(s.water)}</strong></div><div><span>價格結果</span><strong class="${s.priceMove>=0?'sim-positive':'sim-negative'}">${s.priceMove>=0?'+':''}${s.priceMove.toFixed(3)}%</strong></div><div><span>毛損益</span><strong class="${s.gross>=0?'sim-positive':'sim-negative'}">${fmtMoney(s.gross)} 元</strong></div><div><span>進場手續費</span><strong>${fmtMoney(s.entryFee)} 元</strong></div><div><span>出場手續費</span><strong>${fmtMoney(s.exitFee)} 元</strong></div><div><span>交易稅（賣出腿）</span><strong>${fmtMoney(s.tax)} 元</strong></div><div><span>成本後結果</span><strong class="${cls}">${resultText} ${fmtMoney(Math.abs(s.net))} 元</strong></div><div><span>實際報酬率</span><strong class="${cls}">${s.actualReturn>=0?'+':''}${s.a