function updateSimulation(){if(!state.simEntryTime){state.simulation=null;renderSimulation();liveEligibility();return}const entryIndex=state.bars.findIndex(b=>b.startTime===state.simEntryTime);if(entryIndex<0){state.simEntryTime=null;state.simulation=null;renderSimulation();liveEligibility();return}const p=simParams(),x=addCosts(simulateExit(entryIndex,p.direction,p.stopPct,p,false),p.direction,p),priceMove=(p.direction==='LONG'?x.exitPrice/x.entryPrice-1:1-x.exitPrice/x.entryPrice)*100;state.simulation={...x,direction:p.direction,entryIndex,entry:{time:x.entryBar.startTime,price:x.entryPrice},exit:{time:state.bars[x.exitIndex].startTime,price:x.exitPrice},priceMove};renderSimulation();liveEligibility()}
function drawSimulationMarkers(){const cv=$('simChart'),base=$('chart'),r=base.getBoundingClientRect(),dpr=devicePixelRatio||1;cv.width=Math.max(1,r.width*dpr);cv.height=Math.max(1,r.height*dpr);const c=cv.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,r.width,r.height);const s=state.simulation,g=state.geometry;if(!g)return;c.save();if(s&&isTimeRevealed(s.entry.time)){const ex=g.p.l+(s.entryIndex+.5)*g.cw,ey=g.y(s.entry.price),exitVisible=isTimeRevealed(s.exit.time),xx=g.p.l+(s.exitIndex+.5)*g.cw,xy=g.y(s.exit.price);if(exitVisible){c.strokeStyle='#54a8ff';c.lineWidth=2;c.setLineDash([7,4]);c.beginPath();c.moveTo(ex,ey);c.lineTo(xx,xy);c.stroke();c.setLineDash([])}const marks=[{x:ex,y:ey,color:'#54a8ff',label:`進 ${fmtP(s.entry.price)}`}];if(exitVisible)marks.push({x:xx,y:xy,color:s.open?'#ffc857':'#f5f7ff',label:`${s.open?'未出場':'出'} ${fmtP(s.exit.price)}`});for(const m of marks){c.fillStyle=m.color;c.strokeStyle='#08111d';c.lineWidth=2;c.beginPath();c.arc(m.x,m.y,6,0,Math.PI*2);c.fill();c.stroke();c.font='bold 11px system-ui';c.fillStyle=m.color;c.fillText(m.label,Math.min(g.w-92,m.x+8),Math.max(g.p.t+12,m.y-9))}}for(const t of state.autoTrades||[]){if(!isTimeRevealed(t.entry.time))continue;const ex=g.p.l+(t.entryIndex+.5)*g.cw,ey=g.y(t.entry.price),exitVisible=isTimeRevealed(t.exit.time),xx=g.p.l+(t.exitIndex+.5)*g.cw,xy=g.y(t.exit.price),color=t.strategy==='A'?'#73b7ff':'#d9a7ff';if(exitVisible){c.strokeStyle=color;c.lineWidth=1.5;c.setLineDash([4,4]);c.beginPath();c.moveTo(ex,ey);c.lineTo(xx,xy);c.stroke();c.setLineDash([])}const marks=[{x:ex,y:ey,label:`${t.strategy}-${t.direction} 進 ${fmtP(t.entry.price)}`}];if(exitVisible)marks.push({x:xx,y:xy,label:`${t.strategy} 出 ${fmtP(t.exit.price)}`});for(const m of marks){c.fillStyle=color;c.strokeStyle='#08111d';c.lineWidth=2;c.beginPath();c.arc(m.x,m.y,5,0,Math.PI*2);c.fill();c.stroke();c.font='bold 10px system-ui';c.fillStyle=color;c.fillText(m.label,Math.min(g.w-132,m.x+7),Math.max(g.p.t+11,m.y-7))}}c.restore()}
function zigzag(bars,th){if(!bars.length)return{turns:[],candidate:null};const pts=bars.map(b=>({time:b.startTime,price:Number(b.close)}));let dir=0,ext=pts[0],hi=pts[0],lo=pts[0];const turns=[];for(let i=1;i<pts.length;i++){const p=pts[i];if(dir===0){if(p.price>=hi.price)hi=p;if(p.price<=lo.price)lo=p;if((hi.price-p.price)/hi.price>=th){turns.push({...hi,type:'H'});dir=-1;ext=p}else if((p.price-lo.price)/lo.price>=th){turns.push({...lo,type:'L'});dir=1;ext=p}}else if(dir===1){if(p.price>=ext.price)ext=p;else if((ext.price-p.price)/ext.price>=th){turns.push({...ext,type:'H'});dir=-1;ext=p}}else{if(p.price<=ext.price)ext=p;else if((p.price-ext.price)/ext.price>=th){turns.push({...ext,type:'L'});dir=1;ext=p}}}let h=0,l=0;return{turns:turns.map(x=>({...x,label:x.type==='H'?`H${++h}`:`L${++l}`})),candidate:dir===0?null:{...ext,type:dir===1?'H':'L'}}}
