function draw(){const cv=$('chart'),r=cv.getBoundingClientRect(),dpr=devicePixelRatio||1;cv.width=Math.max(1,r.width*dpr);cv.height=Math.max(1,r.height*dpr);const c=cv.getContext('2d');c.scale(dpr,dpr);const bars=state.bars,w=r.width,h=r.height,p={l:64,r:18,t:20,b:32};c.clearRect(0,0,w,h);if(!bars.length){c.fillStyle='#8191a8';c.fillText('此日期尚無 K 線資料',p.l,p.t+15);return}const lo=Math.min(...bars.map(b=>Number(b.low))),hi=Math.max(...bars.map(b=>Number(b.high))),rg=hi-lo||Math.max(1,hi*.001),min=lo-rg*.08,max=hi+rg*.08;const y=v=>p.t+(max-v)/(max-min)*(h-p.t-p.b);const cw=(w-p.l-p.r)/Math.max(1,bars.length);state.geometry={w,h,p,cw,y};c.font='11px system-ui';c.strokeStyle='#27364b';c.fillStyle='#8191a8';for(let i=0;i<=5;i++){const yy=p.t+i*(h-p.t-p.b)/5,v=max-i*(max-min)/5;c.beginPath();c.moveTo(p.l,yy);c.lineTo(w-p.r,yy);c.stroke();c.fillText(fmtP(v),4,yy+4)}if(state.dayRanges.length>1){c.save();c.font='11px system-ui';state.dayRanges.forEach((dr,k)=>{if(k>0){const x=p.l+dr.from*cw;c.strokeStyle='#52657c';c.setLineDash([3,4]);c.beginPath();c.moveTo(x,p.t);c.lineTo(x,h-p.b);c.stroke();c.setLineDash([])}const cx=p.l+((dr.from+dr.to+1)/2)*cw;c.fillStyle='#8191a8';c.fillText(String(dr.date).slice(5),Math.max(p.l,cx-28),h-8)});c.restore()}bars.forEach((b,i)=>{const x=p.l+(i+.5)*cw,o=Number(b.open),cl=Number(b.close),hh=Number(b.high),ll=Number(b.low),up=cl>=o;c.strokeStyle=up?'#ff5f6d':'#36d6a0';c.fillStyle=c.strokeStyle;c.beginPath();c.moveTo(x,y(hh));c.lineTo(x,y(ll));c.stroke();const top=Math.min(y(o),y(cl)),bh=Math.max(1,Math.abs(y(o)-y(cl)));c.fillRect(x-Math.max(1,cw*.28),top,Math.max(2,cw*.56),bh)});if($('overlay').checked&&state.indexBars.length){const ib=state.indexBars.filter(b=>Number(b.close)>0);if(ib.length){const bases={};for(const b of ib){const d=String(b.startTime).slice(0,10);if(!bases[d])bases[d]=Number(b.close)}const pctOf=b=>(Number(b.close)/(bases[String(b.startTime).slice(0,10)]||Number(b.close))-1)*100;const pcts=ib.map(pctOf),plo=Math.min(...pcts),phi=Math.max(...pcts),pr=(phi-plo)||1,pmin=plo-pr*.08,pmax=phi+pr*.08,iy=v=>p.t+(pmax-v)/(pmax-pmin)*(h-p.t-p.b);c.save();c.strokeStyle='#ffc13d';c.fillStyle='#ffc13d';c.lineWidth=1.6;c.beginPath();let started=false;const barTimes=bars.map(x=>new Date(x.startTime).getTime());let bi=0;ib.forEach(b=>{const t=new Date(b.startTime).getTime();while(bi<barTimes.length-1&&barTimes[bi]<t)bi++;if(barTimes[bi]<t)return;const x=p.l+(bi+.5)*cw,yy=iy(pctOf(b));started?c.lineTo(x,yy):c.moveTo(x,yy);started=true});c.stroke();c.font='11px system-ui';for(let i=0;i<=4;i++){const v=pmax-i*(pmax-pmin)/4,yy=iy(v);c.fillText(`${v>=0?'+':''}${v.toFixed(2)}%`,w-55,yy+4)}c.fillText('IX0001',w-65,p.t+10);c.restore()}}if(state.turns.length){c.lineWidth=1.5;c.strokeStyle='#f5f7ff';c.beginPath();state.turns.forEach((t,i)=>{const bi=bars.findIndex(b=>b.startTime===t.time);if(bi<0)return;const x=p.l+(bi+.5)*cw,yy=y(t.price);i?c.lineTo(x,yy):c.moveTo(x,yy)});c.stroke();state.turns.forEach(t=>{const bi=bars.findIndex(b=>b.startTime===t.time);if(bi<0)return;const x=p.l+(bi+.5)*cw,yy=y(t.price);c.fillStyle=t.type==='H'?'#ff5f6d':'#36d6a0';c.beginPath();c.arc(x,yy,4,0,Math.PI*2);c.fill();c.fillText(`${t.label} ${fmtP(t.price)}`,Math.min(w-90,x+5),t.type==='H'?yy-7:yy+15)})}if(state.candidate){const bi=bars.findIndex(b=>b.startTime===state.candidate.time);if(bi>=0){const x=p.l+(bi+.5)*cw,yy=y(state.candidate.price);const last=state.turns.at(-1);if(last){const li=bars.findIndex(b=>b.startTime===last.time);if(li>=0){const lx=p.l+(li+.5)*cw,ly=y(last.price);c.save();c.strokeStyle='#ffc857';c.lineWidth=1.5;c.setLineDash([6,4]);c.beginPath();c.moveTo(lx,ly);c.lineTo(x,yy);c.stroke();c.restore()}}c.strokeStyle='#ffc857';c.setLineDash([4,3]);c.beginPath();c.arc(x,yy,6,0,Math.PI*2);c.stroke();c.setLineDash([]);c.fillStyle='#ffc857';c.fillText(`候選${state.candidate.type} ${fmtP(state.candidate.price)}`,Math.min(w-90,x+5),state.candidate.type==='H'?yy-7:yy+15)}}}
function drawHover(){const cv=$('hoverChart'),base=$('chart'),r=base.getBoundingClientRect(),dpr=devicePixelRatio||1;if(cv.width!==Math.max(1,r.width*dpr)||cv.height!==Math.max(1,r.height*dpr)){cv.width=Math.max(1,r.width*dpr);cv.height=Math.max(1,r.height*dpr)}const c=cv.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,r.width,r.height);const g=state.geometry,i=state.hoverIndex;if(!g||!Number.isInteger(i)||!state.bars[i]||!isBarRevealed(i))return;const b=state.bars[i],x=g.p.l+(i+.5)*g.cw,yy=g.y(Number(b.close));c.strokeStyle='rgba(225,236,246,.78)';c.lineWidth=1;c.setLineDash([5,4]);c.beginPath();c.moveTo(x,g.p.t);c.lineTo(x,g.h-g.p.b);c.moveTo(g.p.l,yy);c.lineTo(g.w-g.p.r,yy);c.stroke();c.setLineDash([]);c.fillStyle='#fff';c.beginPath();c.arc(x,yy,3.5,0,Math.PI*2);c.fill()}
function recompute(payload){state.bars=payload.bars||[];state.sourceBucketCache={};if(state.maskEnabled&&(state.maskResetPending||!Number.isFinite(state.revealThroughMs))){resetRevealBoundary();state.maskResetPending=false}const z=zigzag(state.bars,+$('threshold').value);state.turns=z.turns;state.candidate=z.candidate;$('sSymbol').textContent=payload.name?`${payload.symbol} ${payload.name}`:payload.symbol;$('sDate').textContent=payload.tradeDate;$('sPrice').textContent=state.bars.length?fmtP(state.bars.at(-1).close):'—';$('sBars').textContent=state.bars.length;$('sTurns').textContent=state.turns.length;$('sCandidate').textContent=state.candidate?`候選${state.candidate.type} ${fmtP(state.candidate.price)} @ ${fmtT(state.candidate.time)}`:'—';$('sState').textContent=payload.dataState||'—';renderTable();draw()}
