async function isKnownNonTrading(date){try{const r=await fetch(`/api/calendar/non-trading/${date}`,{cache:'no-store'});return r.ok&&(await r.json()).nonTrading}catch{return false}}
async function previousTradingDates(date,count){const out=[];let d=new Date(date+'T12:00:00');for(let guard=0;out.length<count&&guard<120;guard++){d.setDate(d.getDate()-1);const v=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;if(d.getDay()===0||d.getDay()===6)continue;if(await isKnownNonTrading(v))continue;out.push(v)}return out.reverse()}
async function fetchBars(symbol,date,interval){const r=await fetch(`/api/bars/${encodeURIComponent(symbol)}?date=${encodeURIComponent(date)}&interval=${interval}`,{cache:'no-store'});const text=await r.text();let j={};try{j=text?JSON.parse(text):{}}catch{throw new Error(`HTTP ${r.status} 回傳非 JSON`)}if(!r.ok)throw new Error(j.error||`HTTP ${r.status}`);return j}
async function load(){const symbol=$('symbol').value.trim().toUpperCase(),date=$('date').value,interval=$('interval').value;if(!symbol||!date)return;$('status').textContent=`載入 ${symbol} ${date}…`;$('status').className='';try{let dates=[date];if($('multiDay').checked){const n=Math.max(1,Math.min(20,parseInt($('lookbackDays').value)||1));dates=[...(await previousTradingDates(date,n)),date]}const payloads=[];for(const d of dates){const j=await fetchBars(symbol,d,interval);if(j.dataState==='FUTURE_DATE'&&d===date){payloads.push(j);continue}if(!j.hasData&&d!==date){if(j.source==='SINOPAC_SHIOAJI_NO_DATA'||j.source==='KNOWN_NON_TRADING_DAY'){continue}}payloads.push(j)}const main=payloads.at(-1)||await fetchBars(symbol,date,interval);const combined=[];state.dayRanges=[];for(const j of payloads){if(!j.hasData)continue;const from=combined.length;combined.push(...(j.bars||[]));state.dayRanges.push({date:j.tradeDate,from,to:combined.length-1})}main.bars=combined;main.hasData=combined.length>0;main.dataState=combined.length?'AVAILABLE':main.dataState;if($('overlay').checked&&symbol!=='IX0001'){const idx=[];for(const d of dates){const j=await fetchBars('IX0001',d,interval);if(j.hasData)idx.push(...j.bars)}state.indexBars=idx}else state.indexBars=[];recompute(main);await refreshAnnotations();$('status').textContent=main.hasData?`已載入 ${main.bars.length} 根 K${state.dayRanges.length>1?`（${state.dayRanges.length} 個交易日）`:''}；資料來源：${main.source||'A18_2 LIVE'}。`:main.dataState==='FUTURE_DATE'?`${date} 尚未到達，不進行資料查詢。`:`${date} 目前尚無資料（NO_DATA_YET）。`}catch(e){state.bars=[];state.indexBars=[];state.turns=[];state.candidate=null;state.hoverIndex=null;state.dayRanges=[];state.annotations=[];renderAnnotations();resetAnnotationEditor();drawAnnotationMarkers();$('sDate').textContent=date;$('sPrice').textContent='—';$('sBars').textContent='0';$('sTurns').textContent='0';$('sCandidate').textContent='—';$('sState').textContent='ERROR';renderTable();draw();drawHover();$('status').textContent='載入失敗：'